<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue';

const props = defineProps({ mode: String, indexUrl: String, createUrl: String, storeUrl: String, updateUrl: String, csrf: String, payload: String, errors: String, old: String });
const parseJson = (s, fallback = {}) => { try { return s ? JSON.parse(s) : fallback; } catch { return fallback; } };
const details = parseJson(props.payload); const oldInput = parseJson(props.old); const validationErrors = parseJson(props.errors);
const book = details.book || {};
const form = reactive(Object.fromEntries(['title','isbn','category_id','author_id','publisher_id','seller_id','description','publication_year','pages','language','price','discount_type','discount_value','discount_start_at','discount_end_at','stock','condition','status'].map(key => [key, oldInput[key] ?? book[key] ?? ({language:'English',price:0,discount_type:'none',discount_value:0,stock:1,condition:'good',status:'pending'}[key] ?? '')])));
const preview = ref(details.cover_url || '');
const data = reactive({ books: [], categories: [], stats: {}, pagination: {}, filters: { search: '', status: '', condition: '', category: '' } });
const loading = ref(true); const error = ref(''); let timer; let controller;
const conditionClass = value => ({ new: 'condition-new', like_new: 'condition-like-new', good: 'condition-good', fair: 'condition-fair' }[value] || 'condition-default');
const statusClass = value => ({ approved: 'book-status-approved', pending: 'book-status-pending', rejected: 'book-status-rejected' }[value] || 'book-status-default');
const human = value => value ? value.replaceAll('_', ' ').replace(/^./, c => c.toUpperCase()) : 'Unknown';
async function load(url = location.href, push = false) {
    controller?.abort(); controller = new AbortController(); loading.value = true; error.value = '';
    try { const response = await fetch(url, { credentials: 'same-origin', signal: controller.signal, headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' } }); const result = await response.json(); if (!response.ok) throw new Error(result.message || `Request failed (${response.status})`); data.books = result.books || []; data.categories = result.categories || []; data.stats = result.stats || {}; data.pagination = result.pagination || {}; data.filters = { search: '', status: '', condition: '', category: '', ...(result.filters || {}) }; if (push) history.pushState({}, '', url); }
    catch (e) { if (e.name !== 'AbortError') error.value = e.message || 'Unable to load books.'; }
    finally { loading.value = false; }
}
function buildUrl() { const u = new URL(props.indexUrl, location.origin); for (const [key,value] of Object.entries(data.filters)) if (value) u.searchParams.set(key, value); return u.href; }
function apply(push = true) { load(buildUrl(), push); }
function onSearch() { clearTimeout(timer); timer = setTimeout(() => apply(), 350); }
function goPage(link) { if (link.url) load(link.url, true); }
async function confirmDelete(event) { event.preventDefault(); const form = event.currentTarget; let confirmed = false; if (window.Swal) { const result = await window.Swal.fire({ title: 'Delete book?', text: 'This book listing will be permanently removed.', icon: 'warning', showCancelButton: true, confirmButtonText: 'Delete', cancelButtonText: 'Cancel' }); confirmed = result.isConfirmed; } else confirmed = window.confirm('Delete this book listing?'); if (confirmed) form.submit(); }
function onPop() { load(location.href); }
function previewCover(event) { const file=event.target.files?.[0]; if (preview.value.startsWith('blob:')) URL.revokeObjectURL(preview.value); preview.value=file?.type.startsWith('image/')?URL.createObjectURL(file):details.cover_url||''; }
onMounted(() => { if (props.mode === 'index') load(props.indexUrl + location.search); window.addEventListener('popstate', onPop); });
onBeforeUnmount(() => { clearTimeout(timer); controller?.abort(); window.removeEventListener('popstate', onPop); });
</script>

<template>
    <template v-if="mode==='index'">
    <section class="books-hero"><div class="books-hero-content"><span class="books-hero-badge"><i class="bi bi-book-half"></i> Marketplace Library</span><h1>Every book, beautifully organised.</h1><p>Manage your marketplace inventory, book details, sellers and publication status from one organised workspace.</p></div><div class="books-hero-mark" aria-hidden="true"><i class="bi bi-book"></i></div></section>
    <section class="books-stats"><div class="book-stat-card stat-blue"><div class="book-stat-content"><span>Total Books</span><strong>{{ data.stats.total ?? '—' }}</strong></div><div class="book-stat-icon"><i class="bi bi-collection"></i></div></div><div class="book-stat-card stat-green"><div class="book-stat-content"><span>Approved</span><strong>{{ data.stats.approved ?? '—' }}</strong></div><div class="book-stat-icon"><i class="bi bi-check-circle"></i></div></div><div class="book-stat-card stat-orange"><div class="book-stat-content"><span>Pending</span><strong>{{ data.stats.pending ?? '—' }}</strong></div><div class="book-stat-icon"><i class="bi bi-hourglass-split"></i></div></div><div class="book-stat-card stat-purple"><div class="book-stat-content"><span>Out of Stock</span><strong>{{ data.stats.out_of_stock ?? '—' }}</strong></div><div class="book-stat-icon"><i class="bi bi-box-seam"></i></div></div></section>
    <section class="dashboard-panel books-panel"><div class="books-panel-header"><div class="books-heading-content"><span class="eyebrow"><i class="bi bi-collection"></i> Book directory</span><h5>All Books</h5><p>Search, filter and manage every book listed on SecondBook.</p></div><div class="books-header-action"><a :href="createUrl" class="books-add-btn"><i class="bi bi-plus-lg"></i><span>Add Book</span></a></div></div>
        <form class="book-filters" @submit.prevent="apply()"><div class="book-filter-group book-filter-search"><label for="book-search">Search</label><div class="book-search-field"><i class="bi bi-search"></i><input id="book-search" v-model="data.filters.search" type="text" placeholder="Title, author, seller, ISBN..." autocomplete="off" @input="onSearch"></div></div><div class="book-filter-group"><label for="book-status">Status</label><select id="book-status" v-model="data.filters.status" class="book-filter-select"><option value="">All Status</option><option value="approved">Approved</option><option value="pending">Pending</option><option value="rejected">Rejected</option></select></div><div class="book-filter-group"><label for="book-condition">Condition</label><select id="book-condition" v-model="data.filters.condition" class="book-filter-select"><option value="">All Conditions</option><option value="new">New</option><option value="like_new">Like New</option><option value="good">Good</option><option value="fair">Fair</option></select></div><div class="book-filter-group"><label for="book-category">Category</label><select id="book-category" v-model="data.filters.category" class="book-filter-select"><option value="">All Categories</option><option v-for="category in data.categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></div><div class="book-filter-actions"><button type="submit" class="book-filter-btn"><i class="bi bi-funnel"></i><span>Filter</span></button><a v-if="Object.values(data.filters).some(Boolean)" :href="indexUrl" class="book-clear-filter" @click.prevent="data.filters={search:'',status:'',condition:'',category:''};apply()"><i class="bi bi-x-lg"></i><span>Clear</span></a></div></form>
        <div v-if="error" class="alert alert-danger" role="alert">{{ error }} <button class="btn btn-sm btn-light ms-2" @click="load()">Retry</button></div>
        <div class="books-table-wrap"><table class="books-table"><thead><tr><th class="books-col-id">#</th><th class="books-col-book">Book</th><th class="books-col-category">Category</th><th class="books-col-author">Author</th><th class="books-col-seller">Seller</th><th class="books-col-price">Price</th><th class="books-col-condition">Condition</th><th class="books-col-status">Status</th><th class="books-col-actions">Actions</th></tr></thead><tbody>
            <tr v-if="loading"><td colspan="9" class="text-center py-4">Loading books…</td></tr>
            <tr v-for="book in data.books" v-else :key="book.id"><td><span class="book-id">#{{ book.number }}</span></td><td><div class="book-item-cell"><img v-if="book.cover_url" :src="book.cover_url" :alt="book.title" class="book-cover-image" loading="lazy"><div v-else class="book-cover-placeholder"><i class="bi bi-book"></i></div><div class="book-item-info"><strong :title="book.title">{{ book.title }}</strong><small>{{ book.isbn ? `ISBN: ${book.isbn}` : 'No ISBN' }}</small></div></div></td><td><div class="book-simple-info"><strong>{{ book.category || '—' }}</strong></div></td><td><div class="book-simple-info"><strong :title="book.author || ''">{{ book.author || '—' }}</strong></div></td><td><div class="book-seller-cell"><div class="book-seller-avatar">{{ (book.seller || 'U').slice(0,1).toUpperCase() }}</div><div class="book-seller-info"><strong :title="book.seller">{{ book.seller }}</strong><small>Seller</small></div></div></td><td><span class="book-price">${{ book.price }}</span></td><td><span class="book-condition-pill" :class="conditionClass(book.condition)"><i class="bi bi-circle-fill"></i>{{ human(book.condition) }}</span></td><td><span class="book-status-pill" :class="statusClass(book.status)"><i class="bi bi-circle-fill"></i>{{ human(book.status) }}</span></td><td><div class="book-actions"><a :href="book.show_url" class="book-action-btn book-view-btn" title="View book" aria-label="View book"><i class="bi bi-eye"></i></a><a :href="book.edit_url" class="book-action-btn book-edit-btn" title="Edit book" aria-label="Edit book"><i class="bi bi-pencil"></i></a><form :action="book.delete_url" method="POST" class="book-delete-form" @submit="confirmDelete"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="DELETE"><button type="submit" class="book-action-btn book-delete-btn" title="Delete book" aria-label="Delete book"><i class="bi bi-trash"></i></button></form></div></td></tr>
            <tr v-if="!loading && !data.books.length"><td colspan="9"><div class="books-empty-state"><div class="books-empty-icon"><i class="bi bi-book"></i></div><strong>No books found</strong><span>Try changing your filters or add a new book.</span><a :href="createUrl" class="books-empty-btn"><i class="bi bi-plus-lg"></i> Add Book</a></div></td></tr>
        </tbody></table></div>
        <div v-if="data.pagination.total" class="books-pagination"><div class="books-pagination-info">Showing <strong>{{ data.pagination.first_item || 0 }}</strong> to <strong>{{ data.pagination.last_item || 0 }}</strong> of <strong>{{ data.pagination.total }}</strong> books</div><nav class="books-pagination-pages" aria-label="Books pagination"><button v-for="(link,index) in data.pagination.links || []" :key="index" type="button" class="books-pager-btn" :class="{active:link.active,disabled:!link.url}" :disabled="!link.url" @click="goPage(link)" v-html="link.label.replace('&laquo;','‹').replace('&raquo;','›')"></button></nav></div>
    </section>
    </template>
    <template v-else-if="mode==='create' || mode==='edit'">
        <section v-if="mode==='create'" class="books-hero books-hero-compact"><div class="books-hero-content"><span class="books-hero-badge"><i class="bi bi-plus-circle"></i> New listing</span><h1>Add a new book</h1><p>Fill in the book details, set the price and stock, and upload a cover. New books are saved as pending by default.</p></div><div class="books-hero-mark" aria-hidden="true"><i class="bi bi-book"></i></div></section>
        <div v-else class="books-panel"><div class="books-panel-header"><div class="books-heading-content"><span class="eyebrow"><i class="bi bi-pencil-square"></i> Book Management</span><h5>Edit Book</h5><p>Update book information, pricing, inventory and marketplace settings.</p></div><a :href="indexUrl" class="books-add-btn"><i class="bi bi-arrow-left"></i> Back to Books</a></div></div>
        <form :action="mode==='create'?storeUrl:updateUrl" method="POST" enctype="multipart/form-data" class="book-admin-form"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT"><div v-if="Object.keys(validationErrors).length" class="book-form-alert" role="alert"><i class="bi bi-exclamation-triangle"></i><div><strong>Please fix the following:</strong><ul><li v-for="(messages,key) in validationErrors" :key="key">{{ messages[0] }}</li></ul></div></div>
        <div class="row g-4"><div class="col-lg-8"><div class="dashboard-panel book-form-panel"><div class="book-form-section"><h5>Book information</h5><div class="row g-3"><div class="col-12"><label class="form-label">Title <span class="text-danger">*</span></label><input v-model="form.title" name="title" class="form-control" maxlength="255" required><small v-if="validationErrors.title" class="text-danger">{{ validationErrors.title[0] }}</small></div><div class="col-md-6"><label class="form-label">ISBN</label><input v-model="form.isbn" name="isbn" class="form-control" maxlength="20"></div><div class="col-md-6"><label class="form-label">Language</label><input v-model="form.language" name="language" class="form-control"></div><div class="col-md-6"><label class="form-label">Author</label><select v-model="form.author_id" name="author_id" class="form-select"><option value="">Select author</option><option v-for="item in details.authors||[]" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="col-md-6"><label class="form-label">Category</label><select v-model="form.category_id" name="category_id" class="form-select"><option value="">Select category</option><option v-for="item in details.categories||[]" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="col-md-6"><label class="form-label">Publisher</label><select v-model="form.publisher_id" name="publisher_id" class="form-select"><option value="">Select publisher</option><option v-for="item in details.publishers||[]" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="col-md-6"><label class="form-label">Seller</label><select v-model="form.seller_id" name="seller_id" class="form-select"><option value="">Select seller</option><option v-for="item in details.sellers||[]" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="col-md-6"><label class="form-label">Publication year</label><input v-model="form.publication_year" type="number" name="publication_year" min="1000" :max="new Date().getFullYear()" class="form-control"></div><div class="col-md-6"><label class="form-label">Pages</label><input v-model="form.pages" type="number" min="1" name="pages" class="form-control"></div><div class="col-md-6"><label class="form-label">Condition</label><select v-model="form.condition" name="condition" class="form-select"><option value="new">New</option><option value="like_new">Like New</option><option value="good">Good</option><option value="fair">Fair</option></select></div><div class="col-md-6"><label class="form-label">Listing status</label><select v-model="form.status" name="status" class="form-select"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><div class="col-12"><label class="form-label">Description</label><textarea v-model="form.description" name="description" class="form-control" rows="5"></textarea></div></div></div></div>
        <div class="dashboard-panel book-form-panel mt-4"><div class="book-form-section"><h5>Pricing and inventory</h5><div class="row g-3"><div class="col-md-6"><label class="form-label">Price</label><input v-model="form.price" type="number" name="price" min="0" step="0.01" class="form-control"></div><div class="col-md-6"><label class="form-label">Stock</label><input v-model="form.stock" type="number" name="stock" min="0" class="form-control"></div><div class="col-md-6"><label class="form-label">Discount type</label><select v-model="form.discount_type" name="discount_type" class="form-select"><option value="none">No discount</option><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></div><div class="col-md-6"><label class="form-label">Discount value</label><input v-model="form.discount_value" :disabled="form.discount_type==='none'" type="number" name="discount_value" min="0" step="0.01" class="form-control"></div><div class="col-md-6"><label class="form-label">Discount starts</label><input v-model="form.discount_start_at" type="datetime-local" name="discount_start_at" class="form-control"></div><div class="col-md-6"><label class="form-label">Discount ends</label><input v-model="form.discount_end_at" type="datetime-local" name="discount_end_at" class="form-control"></div></div></div></div></div>
        <div class="col-lg-4"><div class="dashboard-panel book-form-panel"><div class="book-form-section"><h5>Book cover</h5><div class="book-cover-preview"><img v-if="preview" :src="preview" alt="Book cover preview"><div v-else class="book-cover-preview-empty"><i class="bi bi-book"></i><span>No cover selected</span></div></div><label class="form-label mt-3">Cover image</label><input type="file" name="cover" accept="image/*" class="form-control" @change="previewCover"><small class="form-text">JPG, PNG or WEBP. Maximum size 2MB.</small><div v-if="validationErrors.cover" class="text-danger">{{ validationErrors.cover[0] }}</div></div></div></div></div>
        <div class="d-flex justify-content-end gap-2 pt-4"><a :href="indexUrl" class="book-clear-filter"><i class="bi bi-x-lg"></i> Cancel</a><button type="submit" class="books-add-btn"><i class="bi bi-check-circle"></i> {{ mode==='edit'?'Update Book':'Add Book' }}</button></div></form>
    </template>
    <template v-else-if="mode==='show'"><div class="books-panel"><div class="books-panel-header"><div class="books-heading-content"><span class="eyebrow"><i class="bi bi-book"></i> Book Management</span><h5>{{ book.title }}</h5><p>Book details and marketplace listing information.</p></div><div class="books-header-action"><a :href="indexUrl" class="books-add-btn"><i class="bi bi-arrow-left"></i> Back to Books</a><a :href="`${indexUrl}/${book.id}/edit`" class="books-add-btn"><i class="bi bi-pencil"></i> Edit</a></div></div><div class="row g-4 p-4"><div class="col-md-4"><img v-if="details.cover_url" :src="details.cover_url" :alt="book.title" class="img-fluid rounded"><div v-else class="book-cover-placeholder"><i class="bi bi-book"></i></div></div><div class="col-md-8"><h3>{{ book.title }}</h3><p>{{ book.description || 'No description provided.' }}</p><div class="row g-3"><div v-for="[label,value] in [['Category',details.category],['Author',details.author],['Publisher',details.publisher],['Seller',details.seller],['ISBN',book.isbn],['Language',book.language],['Publication year',book.publication_year],['Pages',book.pages],['Price',`$${Number(book.price||0).toFixed(2)}`],['Stock',book.stock],['Condition',human(book.condition)],['Status',human(book.status)]]" :key="label" class="col-sm-6"><strong>{{ label }}:</strong> {{ value || '—' }}</div></div></div></div></div></template>
</template>
